export function PublicPreinscricao() {
  const params = useMemo(() => new URLSearchParams(window.location.search), []);
  const curso = params.get("curso")?.trim() || "Formação de Formadores - CCP";
  const [nome, setNome] = useState("");
  const [apelido, setApelido] = useState("");
  const [telf, setTelf] = useState("");
  const [email, setEmail] = useState(params.get("email") ?? "");
  const [concelho, setConcelho] = useState("");
  const [origem, setOrigem] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [done, setDone] = useState(false);

  async function submit(e: FormEvent) {
    e.preventDefault();
    setError("");
    if (!nome.trim() || !apelido.trim() || !telf.trim() || !email.trim() || !concelho || !origem) {
      setError("Preencha todos os campos para a secretaria o poder contactar.");
      return;
    }
    setBusy(true);
    try {
      await apiPublicPreinscricao({
        nome: nome.trim(),
        apelido: apelido.trim(),
        telf: telf.trim(),
        email: email.trim(),
        concelho,
        origem,
        curso,
      });
      setDone(true);
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Não foi possível enviar. Tente de novo dentro de um minuto.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="min-h-screen bg-white px-4 py-10 sm:px-8">
      <div className="mx-auto w-full max-w-4xl">
        <img
          src="/imagens/ena-logo-nobg.png"
          alt="ENA"
          className="h-10 w-auto mb-10"
          onError={e => { (e.currentTarget as HTMLImageElement).src = "/imagens/ena_logo.svg"; }}
        />
        {done ? (
          <div className="max-w-xl">
            <p className="text-[13px] font-semibold uppercase tracking-[0.14em] text-[#ffa900]">Pré-inscrição recebida</p>
            <h1 className="mt-4 text-2xl font-semibold text-slate-900">Será contactado brevemente.</h1>
            <p className="mt-3 text-sm text-slate-600 leading-relaxed">
              A secretaria da ENA liga ou escreve para {email} / {telf} a propósito de {curso}.
              Não existe área de formando online - o próximo passo é este contacto.
            </p>
          </div>
        ) : (
          <form onSubmit={submit} className="space-y-10" noValidate>
            <p className="text-[13px] font-semibold uppercase tracking-[0.14em] text-[#ffa900]">
              Preencha os seus dados para fazer a pré-inscrição. Será contactado brevemente
            </p>
            {params.get("curso") && (
              <p className="text-sm text-slate-500">Curso: <span className="font-medium text-slate-800">{curso}</span></p>
            )}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-16 gap-y-8">
              <label>
                <span className={labelCls}>Primeiro Nome</span>
                <input className={fieldCls} value={nome} onChange={e => setNome(e.target.value)} autoComplete="given-name" />
              </label>
              <label>
                <span className={labelCls}>Último Nome</span>
                <input className={fieldCls} value={apelido} onChange={e => setApelido(e.target.value)} autoComplete="family-name" />
              </label>
              <label>
                <span className={labelCls}>Contacto Telefónico</span>
                <input className={fieldCls} value={telf} onChange={e => setTelf(e.target.value)} autoComplete="tel" inputMode="tel" />
              </label>
              <label>
                <span className={labelCls}>Email</span>
                <input className={fieldCls} type="email" value={email} onChange={e => setEmail(e.target.value)} autoComplete="email" />
              </label>
              <label>
                <span className={labelCls}>Concelho de residência</span>
                <select className={`${fieldCls} ${concelho ? "text-slate-800" : "text-slate-400"}`} value={concelho} onChange={e => setConcelho(e.target.value)}>
                  <option value="">Selecione um concelho</option>
                  {CONCELHOS.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </label>
              <label>
                <span className={labelCls}>Como tomou conhecimento?</span>
                <select className={`${fieldCls} ${origem ? "text-slate-800" : "text-slate-400"}`} value={origem} onChange={e => setOrigem(e.target.value)}>
                  <option value="">Selecione um opção</option>
                  {ORIGENS.map(o => <option key={o} value={o}>{o}</option>)}
                </select>
              </label>
            </div>
            {error && <p className="text-sm text-red-600">{error}</p>}
            <div className="flex justify-center pt-2">
              <button
                type="submit"
                disabled={busy}
                className="min-w-[220px] px-10 py-3 rounded-full bg-[#1b2330] text-white text-sm font-semibold tracking-wide disabled:opacity-40 hover:bg-black"
              >
                {busy ? "A enviar…" : "INSCREVER-ME"}
              </button>
            </div>
          </form>
        )}
      </div>
    </div>
  );
}

import { useEffect, useRef, useState, type ReactNode } from "react";
import { AppModal } from "./FormKit";

export type Regime = "gold" | "fin" | "sistema";
export type ActionTone = "blue" | "red" | "gray" | "teal" | "purple" | "orange";

const toneCls: Record<ActionTone, string> = {
  blue: "bg-blue-100 text-blue-700 hover:bg-blue-200",
  red: "bg-red-100 text-red-600 hover:bg-red-200",
  gray: "bg-slate-100 text-slate-600 hover:bg-slate-200",
  teal: "bg-teal-100 text-teal-700 hover:bg-teal-200",
  purple: "bg-violet-100 text-violet-700 hover:bg-violet-200",
  orange: "bg-amber-100 text-amber-700 hover:bg-amber-200",
};

export type Crumb = { label: string; onClick?: () => void };

export function RegimeBadge({ regime }: { regime: Regime }) {
  if (regime === "gold") return <span className="inline-flex items-center px-2 py-0.5 rounded-md text-[11px] font-bold bg-amber-500 text-white">Gold</span>;
  if (regime === "fin") return <span className="inline-flex items-center px-2 py-0.5 rounded-md text-[11px] font-bold bg-blue-600 text-white">Financiada</span>;
  return <span className="inline-flex items-center px-2 py-0.5 rounded-md text-[11px] font-bold bg-slate-600 text-white">Sistema</span>;
}

export function PageTrail({ crumbs }: { crumbs: Crumb[] }) {
  if (crumbs.length === 0) return null;
  return (
    <nav aria-label="Percurso" className="flex items-center gap-1.5 min-w-0 text-xs text-slate-500">
      {crumbs.map((c, i) => {
        const last = i === crumbs.length - 1;
        return (
          <span key={`${c.label}-${i}`} className="flex items-center gap-1.5 min-w-0">
            {i > 0 && <span className="text-slate-300 flex-shrink-0">›</span>}
            {c.onClick && !last ? (
              <button type="button" onClick={c.onClick} className="hover:text-slate-800 truncate">{c.label}</button>
            ) : (
              <span className={last ? "font-semibold text-slate-800 truncate" : "truncate"}>{c.label}</span>
            )}
          </span>
        );
      })}
    </nav>
  );
}

export type NextAction = {
  title: string;
  detail: string;
  tone: "error" | "warn" | "info";
  onClick: () => void;
};

export function NextActions({ actions, accent = "gold" }: { actions: NextAction[]; accent?: "gold" | "fin" }) {
  if (actions.length === 0) {
    return (
      <div className={`rounded-xl border px-4 py-3 text-sm ${accent === "gold" ? "border-emerald-200 bg-emerald-50 text-emerald-800" : "border-emerald-200 bg-emerald-50 text-emerald-800"}`}>
        Nada pendente nesta turma para a secretaria.
      </div>
    );
  }
  const ring = {
    error: "border-red-200 bg-red-50",
    warn: "border-amber-200 bg-amber-50",
    info: "border-slate-200 bg-white",
  };
  const mark = {
    error: "text-red-700",
    warn: "text-amber-800",
    info: "text-slate-700",
  };
  return (
    <div>
      <p className="text-xs font-bold uppercase tracking-wider text-slate-500 mb-2">A fazer agora</p>
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
        {actions.map(a => (
          <button key={a.title} type="button" onClick={a.onClick}
            className={`text-left rounded-xl border px-3.5 py-3 hover:shadow-sm transition-shadow ${ring[a.tone]}`}>
            <p className={`text-sm font-bold ${mark[a.tone]}`}>{a.title}</p>
            <p className="text-xs text-slate-600 mt-0.5">{a.detail}</p>
          </button>
        ))}
      </div>
    </div>
  );
}

export type RowAction = {
  label: string;
  icon: ReactNode;
  onClick: () => void;
  tone?: ActionTone;
