          <button key={a.label} type="button" title={a.label} aria-label={a.label} onClick={a.onClick}
            className={`w-7 h-7 inline-flex items-center justify-center rounded-lg transition-colors ${toneCls[a.tone ?? "gray"]}`}>
            {a.icon}
